/**
 * The default Material database of every new main project (MTO Pilot). The client's own MaterialDB.xlsx (7264 materials) is kept in
 * shared/data/material-db-base.ts (generated by scripts/build-material-base.ts). The Article No of a base material is the Article No
 * prefix of Company data followed by the six digits of the Excel number: NLB000001 of the Excel becomes SC000001 here.
 */
export const ARTICLE_PREFIX_DEFAULT = 'SC';
export const ARTICLE_PREFIX_MAX = 6;
export const ARTICLE_PREFIX_ERROR = `Use letters and digits only, 1 to ${ARTICLE_PREFIX_MAX} characters.`;
export const ARTICLE_PREFIX_HINT = 'Starts the Article No of the base materials (for example SC000001). A change applies to main projects created afterwards; existing materials keep their Article No.';
/** The prefix as stored: trimmed and upper case. */
export const normalizeArticlePrefix = (value: unknown) => typeof value === 'string' ? value.trim().toUpperCase() : '';
/** The message when `value` (already trimmed / upper case) cannot be a prefix; '' when it can. */
export const articlePrefixError = (value: string) => new RegExp(`^[A-Z0-9]{1,${ARTICLE_PREFIX_MAX}}$`).test(value) ? '' : ARTICLE_PREFIX_ERROR;
/** The prefix of a Company data record; the default while no record or no value is saved. */
export const articlePrefixOf = (company: { articlePrefix?: unknown } | undefined | null) => normalizeArticlePrefix(company?.articlePrefix) || ARTICLE_PREFIX_DEFAULT;

/** Compact form of the base file: texts are listed once and referenced by index. */
export interface MaterialBaseFile {
  /** Where the data comes from. */
  source: string;
  groups: string[]; parts: string[]; types: string[]; uoms: string[];
  /** [group, article digits, legacy No, material No, diameter, LBS/SCH, description, uom, type, part]: group, uom, type and part are indexes (type and part -1 when empty). */
  rows: [number, string, string, string, string, string, string, number, number, number][];
}
export interface BaseMaterial {
  materialGroup: string; articleDigits: string; legacyNo: string; materialNo: string; dia: string; lbs: string; description: string; uom: string; materialType: string; partMaterial: string;
}
/** The base file as plain materials (article digits without the prefix). */
export function baseMaterials(file: MaterialBaseFile): BaseMaterial[] {
  return file.rows.map(([group, digits, legacyNo, materialNo, dia, lbs, description, uom, type, part]) => ({
    materialGroup: file.groups[group] ?? '', articleDigits: digits, legacyNo, materialNo, dia, lbs, description, uom: file.uoms[uom] ?? '', materialType: type < 0 ? '' : file.types[type], partMaterial: part < 0 ? '' : file.parts[part],
  }));
}
/** Name compare of the catalogs (material parts / types): case and spacing do not matter. */
export const baseKey = (name: string) => name.replace(/\s+/g, ' ').trim().toLowerCase();
